<?php use VazinCMS\Security; $balance=max(0,(float)$invoice['total']-(float)$invoice['paid_amount']); ?><section class="title"><div><h1>فاکتور <?=Security::e($invoice['invoice_number'])?></h1><p><?=Security::e($invoice['customer'].' — '.$invoice['email'])?></p></div><a class="button secondary" href="/admin/invoices">بازگشت</a></section>
<?php if($error):?><div class="alert error"><?=Security::e($error)?></div><?php endif;?><section class="grid order-summary"><article class="panel"><span>مبلغ کل</span><b><?=Security::e($invoice['total'].' '.$invoice['currency'])?></b></article><article class="panel"><span>وصول‌شده</span><b><?=Security::e($invoice['paid_amount'].' '.$invoice['currency'])?></b></article><article class="panel"><span>مانده</span><b><?=Security::e((string)$balance.' '.$invoice['currency'])?></b></article><article class="panel"><span>وضعیت</span><b><?=Security::e($invoice['status'])?></b></article></section>
<section class="panel"><h2>محاسبات فاکتور</h2><dl><dt>مبلغ پایه</dt><dd><?=Security::e($invoice['subtotal'].' '.$invoice['currency'])?></dd><dt>نرخ مالیات</dt><dd><?=Security::e((string)($invoice['tax_rate']??0))?>٪</dd><dt>مبلغ مالیات</dt><dd><?=Security::e((string)($invoice['tax_amount']??0).' '.$invoice['currency'])?></dd><dt>مبلغ نهایی</dt><dd><?=Security::e($invoice['total'].' '.$invoice['currency'])?></dd></dl></section>
<section class="split"><div class="panel"><h2>ثبت پرداخت</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="payment"><label>مبلغ<input type="number" min="0.01" step="0.01" max="<?=$balance?:$invoice['total']?>" name="amount" value="<?=$balance?>" required></label><label>روش پرداخت<input name="method" placeholder="VazinPay، انتقال بانکی، نقدی" required></label><label>شناسه تراکنش<input name="reference"></label><button>ثبت پرداخت قطعی</button></form><?php if($invoice['status']!=='paid'&&in_array($user['role'],['owner','admin'],true)):?><form method="post" data-confirm="فاکتور لغو شود؟"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="cancel"><button class="danger">لغو فاکتور</button></form><?php endif;?></div><div class="panel"><h2>جزئیات</h2><dl><dt>سفارش</dt><dd><?=Security::e((string)$invoice['order_number'])?></dd><dt>تاریخ صدور</dt><dd><?=Security::e((string)$invoice['created_at'])?></dd><dt>سررسید</dt><dd><?=Security::e((string)$invoice['due_at'])?></dd><dt>تاریخ تسویه</dt><dd><?=Security::e((string)$invoice['paid_at'])?></dd></dl></div></section>
<section class="panel"><h2>پرداخت‌ها</h2><div class="table-wrap"><table><thead><tr><th>تاریخ</th><th>مبلغ</th><th>روش</th><th>شناسه</th><th>ثبت‌کننده</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=Security::e($p['created_at'])?></td><td><?=Security::e($p['amount'].' '.$p['currency'])?></td><td><?=Security::e($p['method'])?></td><td><?=Security::e((string)$p['reference'])?></td><td><?=Security::e((string)$p['receiver'])?></td></tr><?php endforeach;?></tbody></table></div></section>
